def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, op_last = history[-1]

    # Count opponent defections
    opp_def = sum(1 for _, o in history if o == 'D')
    my_def = sum(1 for m, _ in history if m == 'D')

    # Break long DD cycles to recover against retaliatory strategies
    if n >= 3:
        last3 = history[-3:]
        if all(m == 'D' and o == 'D' for m, o in last3):
            return 'C'

    if op_last == 'D':
        # Forgive very rare defections (likely noise or initial probe)
        if opp_def <= max(1, n // 10):
            return 'C'
        # If we defected last round too, try cooperating to break cycle
        if my_last == 'D' and opp_def <= n // 2 + 2:
            return 'C'
        return 'D'
    else:
        # Exploit if opponent cooperates despite our recent defections
        if n >= 2:
            recent_my = [m for m, _ in history[-3:]]
            recent_op = [o for _, o in history[-3:]]
            if all(m == 'D' for m in recent_my) and all(o == 'C' for o in recent_op):
                return 'D'
        # Endgame: if behind, occasionally defect
        if n > 90:
            my_score = sum(3 if m == 'C' and o == 'C' else 5 if m == 'D' and o == 'C' else 1 if m == 'D' and o == 'D' else 0 for m, o in history)
            opp_score = sum(3 if o == 'C' and m == 'C' else 5 if o == 'D' and m == 'C' else 1 if o == 'D' and m == 'D' else 0 for m, o in history)
            if my_score < opp_score and rng.random() < 0.3:
                return 'D'
        return 'C'
